loadRemoteState=async function(){
  if(!firebase)return;
  try{
    const {collection,getDocs}=firebase.firestoreSdk;
    const [usersSnap,eventsSnap,objectsSnap,activitiesSnap,costsSnap,documentsSnap]=await Promise.all([getDocs(collection(firebase.db,'users')),getDocs(collection(firebase.db,'events')),getDocs(collection(firebase.db,'objects')),getDocs(collection(firebase.db,'activities')),getDocs(collection(firebase.db,'costs')),getDocs(collection(firebase.db,'documents'))]);
    state.users=usersSnap.docs.map(d=>({id:d.id,...d.data()}));
    state.documents=documentsSnap.docs.map(d=>({id:d.id,...d.data()}));
    state.objects=objectsSnap.docs.map(d=>({dbId:d.id,...d.data()})).filter(o=>o.active!==false).map(o=>({id:o.code,dbId:o.dbId,title:o.title||'',product:o.product||'',objectType:o.objectType||'',priority:o.priority||'Média',budget:Number(o.budget||0),spent:Number(o.spent||0),start:o.plannedStart||'',due:o.plannedEnd||'',duration:Number(o.duration||0),status:o.status||'À iniciar',interventionType:o.interventionType||'',owner:o.ownerName||'',area:o.primaryArea||o.area||'',primaryArea:o.primaryArea||o.area||'',secondaryArea:o.secondaryArea||'',observation:o.observation||'',description:o.description||o.observation||'',progress:Number(o.progress||0)}));
    state.events=eventsSnap.docs.map(d=>{const e=d.data();return{id:d.id,dbId:d.id,objectId:e.objectCode||'',date:firebaseDateTime(e.eventAt),type:e.eventType||'',status:e.status||'',progress:normalizeEventProgress(e.status,e.progress),text:e.description||'',user:e.createdByName||'',productDelivery:e.productDelivery||'',responsible:e.responsible||'',area:e.area||'',observation:e.observation||'',assignedTo:e.assignedTo||'',assignedToName:e.assignedToName||'',assignedBy:e.assignedBy||e.createdBy||'',assignedByName:e.assignedByName||e.createdByName||'',receivedAt:e.receivedAt?.toDate?.().toISOString()||e.receivedAt||'',receivedBy:e.receivedBy||'',assigneeNote:e.assigneeNote||'',hasForecast:!!e.hasForecast,forecastStart:e.forecastStart||'',forecastEnd:e.forecastEnd||'',forecastDays:e.forecastDays??null,hasExecution:!!e.hasExecution,executionStart:e.executionStart||'',executionEnd:e.executionEnd||'',executionDays:e.executionDays??null}}).sort((a,b)=>String(b.date).localeCompare(String(a.date)));
    state.activities=activitiesSnap.docs.map(d=>{const a=d.data();return{id:d.id,objectId:a.objectCode||'',title:a.title||'',owner:a.ownerName||'',status:a.status||'',progress:Number(a.progress||0)}});
    state.costs=costsSnap.docs.map(d=>{const c=d.data();return{id:d.id,objectId:c.objectCode||'',date:c.occurredOn||'',category:c.category||'',supplier:c.supplier||'',value:Number(c.amount||0)}}).sort((a,b)=>String(b.date).localeCompare(String(a.date)));
    recalculateAllProgress();save();
  }catch(error){toast('Falha ao carregar os dados do Firebase: '+error.message);throw error}
};

function firebaseDateTime(value){const dateValue=value?.toDate?.()||value;if(!dateValue)return'';const parsed=dateValue instanceof Date?dateValue:new Date(dateValue);return Number.isNaN(parsed.getTime())?'':parsed.toLocaleString('sv-SE').slice(0,16)}

function progressEvents(objectId){return state.events.filter(e=>e.objectId===objectId&&e.status)}
function calculateProgress(objectId){const events=progressEvents(objectId);return events.length?Math.round(events.filter(e=>e.status==='finalizado').length/events.length*100):0}
function recalculateAllProgress(){state.objects.forEach(o=>o.progress=calculateProgress(o.id))}
function isCompletedEventStatus(status){return ['finalizado','concluido','concluído'].includes(String(status||'').toLowerCase())}
function normalizeEventProgress(status,value){if(isCompletedEventStatus(status))return 100;const number=Number(value);return Number.isFinite(number)?Math.max(0,Math.min(99,Math.round(number))):0}
function eventProgressBar(event){const progress=normalizeEventProgress(event.status,event.progress);return `<div class="event-progress" aria-label="Execução do andamento: ${progress}%"><div class="event-progress-head"><span>EXECUÇÃO DO ANDAMENTO</span><strong>${progress}%</strong></div><div class="event-progress-track"><i style="--event-progress:${progress}%"></i></div></div>`}
function syncEventProgress(statusField){const form=statusField.form,input=form?.elements.progress,output=form?.querySelector('[data-event-progress-value]');if(!input)return;const completed=isCompletedEventStatus(statusField.value);input.max=completed?'100':'99';input.value=completed?'100':String(normalizeEventProgress(statusField.value,input.value));input.disabled=completed;if(output)output.textContent=input.value+'%'}
function updateEventProgress(input){const status=input.form?.elements.status;if(status&&isCompletedEventStatus(status.value))input.value='100';else input.value=String(normalizeEventProgress(status?.value,input.value));const output=input.form?.querySelector('[data-event-progress-value]');if(output)output.textContent=input.value+'%'}
function assignedEvents(){return state.events.filter(e=>e.assignedTo&&(e.assignedTo===session?.id||e.assignedToName===session?.name))}
function senderReceipts(){return state.events.filter(e=>e.assignedBy&&(e.assignedBy===session?.id||e.assignedByName===session?.name)&&e.receivedAt)}

function assignmentNotice(){
  const pending=assignedEvents().filter(e=>!e.receivedAt),receipts=senderReceipts();
  if(!pending.length&&!receipts.length)return'';
  return `<section class="assignment-alerts">${pending.length?`<button class="assignment-alert pending" onclick="openAssignments()"><strong>${pending.length} andamento${pending.length===1?'':'s'} para você</strong><span>Abra para confirmar o recebimento, aplicar e atualizar o status.</span></button>`:''}${receipts.slice(0,3).map(e=>`<div class="assignment-alert received"><strong>Andamento recebido</strong><span>${esc(e.assignedToName)} abriu ${esc(e.objectId)}.</span></div>`).join('')}</section>`;
}

const baseRender=render;
render=function(){baseRender();setupLoginLogo();if(session){const content=document.querySelector('.content');if(content)content.insertAdjacentHTML('afterbegin',assignmentNotice());setupNotificationBell();setupEditObjectButton();setupObjectDetailSummary();setupObjectDetailTabs()}};

function setupLoginLogo(){
  const seal=document.querySelector('.login .seal');if(!seal)return;
  seal.innerHTML='<img src="/assets/logo_semed.jpeg?v=20260805" alt="Secretaria Municipal de Educação de Uberaba" onerror="retryLoginLogo(this)"><span class="semed-logo-fallback" hidden><strong>SEMED</strong><small>SECRETARIA MUNICIPAL DE EDUCAÇÃO · UBERABA</small></span>';
  seal.classList.add('semed-logo')
}
function retryLoginLogo(image){if(!image.dataset.retry){image.dataset.retry='1';setTimeout(()=>{image.src='/assets/logo_semed.jpeg?reload='+Date.now()},250);return}image.hidden=true;image.nextElementSibling.hidden=false}

function setupObjectDetailSummary(){
  if(view!=='detail'||!selected)return;const o=state.objects.find(item=>item.id===selected),summary=document.querySelector('.detail-grid .summary');if(!o||!summary||summary.dataset.enhanced)return;
  summary.dataset.enhanced='true';summary.classList.add('detail-summary-enhanced');const cards=[...summary.children],byLabel=label=>cards.find(card=>card.querySelector('span')?.textContent.trim()===label),execution=byLabel('Execução física'),deadline=byLabel('Prazo final'),product=byLabel('Produto / Entrega');
  execution?.classList.add('summary-compact','summary-progress');deadline?.classList.add('summary-compact','summary-deadline');product?.classList.add('summary-product');
  if(deadline){const start=document.createElement('div');start.className='summary-compact summary-start';start.innerHTML=`<span>Data de Início</span><strong>${date(o.start)}</strong>`;deadline.insertAdjacentElement('beforebegin',start)}
}

function setupObjectDetailTabs(){
  if(view!=='detail'||!selected)return;const tabs=document.querySelector('.detail-grid .tabs'),panel=tabs?.closest('.panel');if(!tabs||!panel||tabs.dataset.functional)return;tabs.dataset.functional='true';
  let sibling=tabs.nextElementSibling;while(sibling){const next=sibling.nextElementSibling;sibling.remove();sibling=next}
  panel.insertAdjacentHTML('beforeend','<div class="detail-tab-content" id="detailTabContent"></div>');showDetailTab('activities',selected)
}

function detailTabData(objectId){return{activities:state.activities.filter(item=>item.objectId===objectId),costs:state.costs.filter(item=>item.objectId===objectId),documents:(state.documents||[]).filter(item=>item.objectCode===objectId||item.objectId===objectId||item.objectId===state.objects.find(o=>o.id===objectId)?.dbId)}}
function emptyDetailTab(){return'<div class="detail-tab-empty">AINDA NÃO HÁ INFORMAÇÕES PARA ESTA OPÇÃO!</div>'}
function safeDocumentUrl(value){try{const url=new URL(value,location.origin);return ['http:','https:'].includes(url.protocol)?url.href:''}catch{return''}}

function showDetailTab(tabName,objectId){
  const tabs=document.querySelector('.detail-grid .tabs'),content=document.getElementById('detailTabContent');if(!tabs||!content)return;const data=detailTabData(objectId),labels={activities:`Atividades (${data.activities.length})`,costs:`Custos (${data.costs.length})`,documents:`Documentos (${data.documents.length})`};
  tabs.innerHTML=Object.entries(labels).map(([key,label])=>`<button type="button" class="${tabName===key?'active':''}" onclick="showDetailTab('${key}','${objectId}')">${label}</button>`).join('');
  if(tabName==='activities')content.innerHTML=data.activities.length?`<div class="detail-list">${data.activities.map(a=>`<article><div><strong>${esc(a.title)}</strong><small>${esc(a.owner)}</small></div><span class="pill ${statusClass(a.status)}">${esc(a.status)} · ${Number(a.progress||0)}%</span></article>`).join('')}</div>`:emptyDetailTab();
  else if(tabName==='costs')content.innerHTML=data.costs.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Categoria</th><th>Fornecedor</th><th>Valor</th></tr></thead><tbody>${data.costs.map(c=>`<tr><td>${date(c.date)}</td><td>${esc(c.category)}</td><td>${esc(c.supplier)}</td><td><strong>${money(c.value)}</strong></td></tr>`).join('')}</tbody></table></div>`:emptyDetailTab();
  else content.innerHTML=data.documents.length?`<div class="detail-list documents-list">${data.documents.map(d=>{const documentUrl=safeDocumentUrl(d.downloadURL||d.url);return`<article><div><strong>${esc(d.fileName||d.name||d.title||'DOCUMENTO')}</strong><small>${esc(d.category||d.contentType||'ARQUIVO')} ${d.uploadedByName?'· '+esc(d.uploadedByName):''}</small></div>${documentUrl?`<a class="btn secondary" href="${esc(documentUrl)}" target="_blank" rel="noopener">Abrir</a>`:'<span class="pill blue">REGISTRADO</span>'}</article>`}).join('')}</div>`:emptyDetailTab()
}

function openAssignments(){
  const items=assignedEvents().sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  modal(`<div class="modal-head"><h2>Meus andamentos</h2><button class="icon-btn" onclick="closeModal()">✕</button></div><div class="assignment-list">${items.map(e=>`<button onclick="openAssignedEvent('${e.id}')"><span class="assignment-content"><strong>${esc(e.objectId)} · ${esc(e.productDelivery||e.type)}</strong><small>${esc(e.text||'Sem descrição')} · enviado por ${esc(e.assignedByName||e.user)}</small>${eventProgressBar(e)}</span><span class="pill ${e.status==='finalizado'?'green':e.receivedAt?'blue':'amber'}">${e.receivedAt?eventStatusLabel(e.status):'Novo'}</span></button>`).join('')||'<div class="empty">Nenhum andamento direcionado para você.</div>'}</div>`)
}

function eventStatusLabel(status){return({a_iniciar:'À iniciar',a_executar:'À executar',em_andamento:'Em andamento',em_execucao:'Em execução',parado:'Parado',cancelado:'Cancelado',arquivado:'Arquivado',finalizado:'Finalizado'})[status]||status||'Sem status'}

eventModal=function(id=''){
  const users=(state.users||[]).filter(u=>u.active!==false);
  modal(`<div class="modal-head"><h2>Novo andamento</h2><button class="icon-btn" onclick="closeModal()">✕</button></div><form class="form-grid" onsubmit="addEvent(event)"><div class="field"><label>Objeto</label><select name="objectId">${state.objects.map(o=>`<option ${id===o.id?'selected':''} value="${o.id}">${o.id} — ${esc(o.title)}</option>`).join('')}</select></div><div class="field"><label>Tipo de evento</label><select name="type"><option>Andamento</option><option>Pendência</option><option>Decisão</option><option>Comentário</option><option>Status</option></select></div><div class="field"><label>Status</label><select name="status" onchange="handleEventStatus(this)" required><option value="a_iniciar">À iniciar</option><option value="a_executar">À executar</option><option value="em_andamento">Em andamento</option><option value="em_execucao">Em execução</option><option value="parado">Parado</option><option value="cancelado">Cancelado</option><option value="arquivado">Arquivado</option><option value="finalizado">Finalizado</option></select></div><div class="field"><label>Direcionar para usuário</label><select name="assignedTo"><option value="">Sem direcionamento</option>${users.map(u=>`<option value="${u.id}">${esc(u.fullName||u.email)}</option>`).join('')}</select></div><div class="field span2"><label>Descrição</label><textarea name="text" rows="4" required></textarea><small id="descriptionStatusHint" class="field-hint">Informe os detalhes deste andamento.</small></div><div class="field"><label>Produto / Entrega</label><input name="productDelivery"></div><div class="field"><label>Responsável</label><input name="responsible"></div><div class="field"><label>Área</label><select name="area"><option value="">Selecione</option><option>Gestão Pedagógica</option><option>Infraestrutura</option><option>Tecnologia</option><option>Logística</option><option>Gestão de Pessoas</option></select></div><div class="field"><label>Observação</label><textarea name="observation" rows="3"></textarea></div><div class="span2"><label class="section-label">Este andamento terá controle de datas?</label><div class="date-options"><label class="date-toggle"><input type="checkbox" name="includeForecast" onchange="toggleDateSection('forecastDates',this.checked)"><span>Data de Previsão</span></label><label class="date-toggle"><input type="checkbox" name="includeExecution" onchange="toggleDateSection('executionDates',this.checked)"><span>Data de Execução</span></label></div></div><section class="date-section" id="forecastDates" hidden><div class="field"><label>Data de Previsão Início</label><input type="date" name="forecastStart" onchange="calculateDatePeriod('forecast')"></div><div class="field"><label>Data de Previsão Término</label><input type="date" name="forecastEnd" onchange="calculateDatePeriod('forecast')"></div><output class="days-result" id="forecastDays"><strong>—</strong><small>Dias previstos</small></output></section><section class="date-section" id="executionDates" hidden><div class="field"><label>Data de Execução Início</label><input type="date" name="executionStart" onchange="calculateDatePeriod('execution')"></div><div class="field"><label>Data de Execução Término</label><input type="date" name="executionEnd" onchange="calculateDatePeriod('execution')"></div><output class="days-result" id="executionDays"><strong>—</strong><small>Dias de execução</small></output></section><div class="span2 actions"><button type="button" class="btn secondary" onclick="closeModal()">Cancelar</button><button class="btn" id="registerHistoryBtn">Registrar no histórico</button></div></form>`)
  const form=document.querySelector('.modal form'),descriptionField=form?.elements.text?.closest('.field'),statusField=form?.elements.status;if(form&&descriptionField&&statusField){descriptionField.insertAdjacentHTML('beforebegin','<div class="field span2 event-progress-field"><label>Percentual de execução do andamento</label><div><input type="range" name="progress" min="0" max="99" value="0" oninput="updateEventProgress(this)"><output data-event-progress-value>0%</output></div><small>O percentual 100% é aplicado automaticamente somente ao status Finalizado.</small></div>');statusField.addEventListener('change',()=>syncEventProgress(statusField));syncEventProgress(statusField)}
};

addEvent=async function(e){
  e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),obj=state.objects.find(o=>o.id===f.objectId),assigned=state.users.find(u=>u.id===f.assignedTo),description=f.text||'',details={productDelivery:f.productDelivery||'',responsible:f.responsible||'',area:f.area||'',observation:f.observation||''},hasForecast=f.includeForecast==='on',hasExecution=f.includeExecution==='on',forecastDays=hasForecast?calculateDatePeriod('forecast'):null,executionDays=hasExecution?calculateDatePeriod('execution'):null;
  if((hasForecast&&forecastDays===null)||(hasExecution&&executionDays===null)){e.target.reportValidity();return}
  const eventProgress=normalizeEventProgress(f.status,f.progress),assignment={assignedTo:f.assignedTo||'',assignedToName:assigned?.fullName||'',assignedBy:session.id||'',assignedByName:session.name},schedule={hasForecast,hasExecution,...(hasForecast?{forecastStart:f.forecastStart,forecastEnd:f.forecastEnd,forecastDays}:{}),...(hasExecution?{executionStart:f.executionStart,executionEnd:f.executionEnd,executionDays}:{})},localEvent={id:crypto.randomUUID(),objectId:f.objectId,type:f.type,status:f.status,progress:eventProgress,text:description,...details,...assignment,...schedule,date:new Date().toLocaleString('sv-SE').slice(0,16),user:session.name};
  const projected=[localEvent,...state.events],relevant=projected.filter(x=>x.objectId===f.objectId&&x.status),progress=relevant.length?Math.round(relevant.filter(x=>x.status==='finalizado').length/relevant.length*100):0;
  if(firebase){try{const {collection,doc,writeBatch,serverTimestamp}=firebase.firestoreSdk,eventRef=doc(collection(firebase.db,'events')),auditRef=doc(collection(firebase.db,'audit')),batch=writeBatch(firebase.db),eventData={objectId:obj?.dbId,objectCode:f.objectId,eventType:f.type,status:f.status,progress:eventProgress,description,...details,...assignment,...schedule,createdBy:session.id,createdByName:session.name,eventAt:serverTimestamp()};batch.set(eventRef,eventData);if(obj?.dbId)batch.update(doc(firebase.db,'objects',obj.dbId),{progress,updatedAt:serverTimestamp()});batch.set(auditRef,{userId:session.id,userName:session.name,action:'CREATE',entity:'events',recordId:eventRef.id,newData:eventData,createdAt:serverTimestamp()});await batch.commit();localEvent.id=eventRef.id;localEvent.dbId=eventRef.id}catch(error){return toast('Erro ao registrar andamento: '+error.message)}}
  state.events.unshift(localEvent);if(obj)obj.progress=progress;save();closeModal();toast(assigned?'Andamento direcionado para '+assigned.fullName+'.':'Andamento registrado.');render()
};

async function openAssignedEvent(id){
  const e=state.events.find(x=>x.id===id||x.dbId===id);if(!e)return;
  if(!e.receivedAt){e.receivedAt=new Date().toISOString();e.receivedBy=session.id||session.name;if(firebase&&e.dbId){try{await firebase.firestoreSdk.updateDoc(firebase.firestoreSdk.doc(firebase.db,'events',e.dbId),{receivedAt:firebase.firestoreSdk.serverTimestamp(),receivedBy:session.id,receivedByName:session.name})}catch(error){return toast('Não foi possível confirmar o recebimento: '+error.message)}}save()}
  closeModal();modal(`<div class="modal-head"><h2>Atualizar andamento</h2><button class="icon-btn" onclick="closeModal()">✕</button></div><div class="notice">Recebimento confirmado para ${esc(e.assignedByName||e.user)}.</div><form class="form-grid" onsubmit="updateAssignedEvent(event,'${e.id}')"><div class="field span2"><label>Objeto / Entrega</label><input value="${esc(e.objectId+' — '+(e.productDelivery||e.type))}" disabled></div><div class="field"><label>Status</label><select name="status">${['a_iniciar','a_executar','em_andamento','em_execucao','parado','cancelado','arquivado','finalizado'].map(s=>`<option value="${s}" ${e.status===s?'selected':''}>${eventStatusLabel(s)}</option>`).join('')}</select></div><div class="field"><label>Responsável</label><input value="${esc(e.assignedToName)}" disabled></div><div class="field span2 event-progress-field"><label>Percentual de execução do andamento</label><div><input type="range" name="progress" min="0" max="99" value="${normalizeEventProgress(e.status,e.progress)}" oninput="updateEventProgress(this)"><output data-event-progress-value>${normalizeEventProgress(e.status,e.progress)}%</output></div><small>O percentual 100% é aplicado automaticamente somente ao status Finalizado.</small></div><div class="field span2"><label>Informação do responsável</label><textarea name="assigneeNote" rows="4">${esc(e.assigneeNote||'')}</textarea></div><div class="span2 actions"><button type="button" class="btn secondary" onclick="closeModal()">Fechar</button><button class="btn">Salvar atualização</button></div></form>`);const form=document.querySelector('.modal form'),statusField=form?.elements.status;if(statusField){statusField.addEventListener('change',()=>syncEventProgress(statusField));syncEventProgress(statusField)}
}

async function updateAssignedEvent(ev,id){
  ev.preventDefault();const e=state.events.find(x=>x.id===id||x.dbId===id),f=Object.fromEntries(new FormData(ev.target));if(!e)return;e.status=f.status;e.progress=normalizeEventProgress(f.status,f.progress);e.assigneeNote=f.assigneeNote||'';const obj=state.objects.find(o=>o.id===e.objectId),progress=calculateProgress(e.objectId);
  if(firebase&&e.dbId){try{const {doc,collection,writeBatch,serverTimestamp}=firebase.firestoreSdk,batch=writeBatch(firebase.db);batch.update(doc(firebase.db,'events',e.dbId),{status:e.status,progress:e.progress,assigneeNote:e.assigneeNote,updatedAt:serverTimestamp()});if(obj?.dbId)batch.update(doc(firebase.db,'objects',obj.dbId),{progress,updatedAt:serverTimestamp()});batch.set(doc(collection(firebase.db,'audit')),{userId:session.id,userName:session.name,action:'UPDATE_ASSIGNMENT',entity:'events',recordId:e.dbId,newData:{status:e.status,progress:e.progress,assigneeNote:e.assigneeNote},createdAt:serverTimestamp()});await batch.commit()}catch(error){return toast('Erro ao atualizar andamento: '+error.message)}}
  if(obj)obj.progress=progress;save();closeModal();toast(`Status atualizado. Progresso do objeto: ${progress}%.`);render()
}

const loadWithAssignments=loadRemoteState;
loadRemoteState=async function(){
  await loadWithAssignments();state.notificationReads=[];
  if(!firebase||!session?.id)return;
  try{const {collection,getDocs,query,where}=firebase.firestoreSdk,snap=await getDocs(query(collection(firebase.db,'notificationReads'),where('userId','==',session.id)));state.notificationReads=snap.docs.map(d=>d.data().eventId)}catch(error){console.warn('Não foi possível carregar notificações lidas',error)}
};

function generalNotifications(){return state.events.filter(e=>!e.assignedTo&&e.user!==session?.name&&!state.notificationReads?.includes(e.id))}
function availableNotifications(){return[...assignedEvents().filter(e=>!e.receivedAt).map(e=>({kind:'assigned',event:e,title:'Andamento direcionado',text:`${e.objectId} · ${e.productDelivery||e.text||e.type}`})),...generalNotifications().map(e=>({kind:'general',event:e,title:'Novo andamento',text:`${e.objectId} · ${e.text||e.type}`})),...senderReceipts().map(e=>({kind:'receipt',event:e,title:'Recebimento confirmado',text:`${e.assignedToName} recebeu ${e.objectId}`}))]}

function setupNotificationBell(){
  const buttons=document.querySelectorAll('.top-actions .icon-btn'),bell=buttons[1];if(!bell)return;const notifications=availableNotifications();
  bell.innerHTML=`●${notifications.length?` <span class="pill red">${notifications.length}</span>`:''}`;bell.title='Notificações';bell.onclick=openNotificationCenter;bell.onmouseenter=showNotificationDropdown;bell.onmouseleave=()=>setTimeout(hideNotificationDropdown,180);
}

function showNotificationDropdown(){
  hideNotificationDropdown();const bell=document.querySelectorAll('.top-actions .icon-btn')[1],items=availableNotifications().slice(0,6);if(!bell)return;
  bell.insertAdjacentHTML('afterend',`<div class="notification-dropdown" id="notificationDropdown" onmouseenter="this.dataset.hover='1'" onmouseleave="this.remove()"><strong>Notificações</strong>${items.map(n=>`<div><span class="pill ${n.kind==='assigned'?'amber':'blue'}">${n.kind==='assigned'?'Para você':'Informação'}</span><p>${esc(n.text)}</p></div>`).join('')||'<p class="empty-mini">Nenhuma notificação disponível.</p>'}<button class="btn block" onclick="openNotificationCenter()">Ver todas</button></div>`)
}
function hideNotificationDropdown(){const box=document.getElementById('notificationDropdown');if(box&&!box.dataset.hover)box.remove()}

function openNotificationCenter(){
  hideNotificationDropdown();const items=availableNotifications();modal(`<div class="modal-head"><h2>Central de notificações</h2><button class="icon-btn" onclick="closeModal()">✕</button></div><div class="notification-center">${items.map(n=>`<article><div><span class="pill ${n.kind==='assigned'?'amber':n.kind==='receipt'?'green':'blue'}">${esc(n.title)}</span><p>${esc(n.text)}</p><small>${esc(n.event.date||'')}</small></div>${n.kind==='assigned'?`<button class="btn" onclick="receiveAssignedEvent('${n.event.id}')">Receber andamento</button>`:n.kind==='general'?`<button class="btn secondary" onclick="markNotificationRead('${n.event.id}')">Dar como lido</button>`:'<span class="pill green">Recebido</span>'}</article>`).join('')||'<div class="empty">Nenhuma notificação disponível.</div>'}</div>`)
}

async function receiveAssignedEvent(id){
  const e=state.events.find(x=>x.id===id||x.dbId===id);if(!e)return;if(!e.receivedAt){e.receivedAt=new Date().toISOString();e.receivedBy=session.id||session.name;if(firebase&&e.dbId){try{await firebase.firestoreSdk.updateDoc(firebase.firestoreSdk.doc(firebase.db,'events',e.dbId),{receivedAt:firebase.firestoreSdk.serverTimestamp(),receivedBy:session.id,receivedByName:session.name})}catch(error){return toast('Não foi possível receber o andamento: '+error.message)}}save()}closeModal();openAssignedEvent(id)
}

async function markNotificationRead(eventId){
  state.notificationReads=state.notificationReads||[];if(!state.notificationReads.includes(eventId))state.notificationReads.push(eventId);
  if(firebase&&session?.id){try{const {doc,setDoc,serverTimestamp}=firebase.firestoreSdk;await setDoc(doc(firebase.db,'notificationReads',`${session.id}_${eventId}`),{userId:session.id,eventId,readAt:serverTimestamp()},{merge:true})}catch(error){return toast('Não foi possível marcar como lida: '+error.message)}}save();closeModal();toast('Notificação marcada como lida.');render()
}

accessView=function(){
  if(session.role!=='administrador')return head('Acesso restrito','Perfis de acesso','Somente administradores podem gerenciar perfis.')+'<div class="notice">Seu perfil não possui permissão para acessar este módulo.</div>';
  return head('Administração','Perfis de acesso','Crie usuários, altere dados, redefina senhas e enquadre cada pessoa no perfil correto.',`<button class="btn" onclick="userEditor()">+ Criar usuário</button>`)+`<section class="role-grid">${accessRoles.map(r=>`<article class="role-card"><span class="role-icon">${r[1][0]}</span><div><h3>${r[1]}</h3><p>${r[2]}</p></div></article>`).join('')}</section><section class="panel" style="margin-top:15px"><div class="panel-head"><h2>Usuários do sistema</h2><span class="pill blue">${state.users.length} usuário${state.users.length===1?'':'s'}</span></div><div class="table-wrap"><table><thead><tr><th>Usuário</th><th>E-mail</th><th>Perfil</th><th>Situação</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td><strong>${esc(u.fullName)}</strong></td><td>${esc(u.email)}</td><td><span class="pill blue">${roleLabel(u.role)}</span></td><td><span class="pill ${u.active?'green':'red'}">${u.active?'Ativo':'Inativo'}</span></td><td><button class="btn secondary" onclick="userEditor('${u.id}')">Editar</button></td></tr>`).join('')}</tbody></table></div></section>`
};

function userEditor(uid=''){
  const u=state.users.find(x=>x.id===uid)||{};modal(`<div class="modal-head"><h2>${uid?'Editar usuário':'Criar usuário'}</h2><button class="icon-btn" onclick="closeModal()">✕</button></div><form class="form-grid" onsubmit="manageAccessUser(event)"><input type="hidden" name="uid" value="${esc(uid)}"><div class="field"><label>Nome completo</label><input name="fullName" value="${esc(u.fullName||'')}" required></div><div class="field"><label>E-mail institucional</label><input name="email" type="email" value="${esc(u.email||'')}" required></div><div class="field"><label>${uid?'Nova senha':'Senha inicial'}</label><input name="password" type="password" minlength="6" ${uid?'placeholder="Deixe vazio para manter a senha"':'required'}><small>Mínimo de 6 caracteres.</small></div><div class="field"><label>Perfil de acesso</label><select name="role">${accessRoles.map(r=>`<option value="${r[0]}" ${u.role===r[0]?'selected':''}>${r[1]}</option>`).join('')}</select></div><div class="field span2"><label class="date-toggle"><input type="checkbox" name="active" ${u.active!==false?'checked':''}><span>Usuário ativo</span></label></div><div class="span2 actions"><button type="button" class="btn secondary" onclick="closeModal()">Cancelar</button><button class="btn">${uid?'Salvar alterações':'Criar usuário'}</button></div></form>`)
}

async function manageAccessUser(ev){
  ev.preventDefault();const data=Object.fromEntries(new FormData(ev.target)),payload={uid:data.uid||undefined,fullName:data.fullName,email:data.email,password:data.password||undefined,role:data.role,active:data.active==='on'};
  if(firebase){try{const callable=firebase.functionsSdk.httpsCallable(firebase.functions,'manageUser'),result=await callable(payload),user={id:result.data.uid,...result.data},index=state.users.findIndex(u=>u.id===user.id);index>=0?state.users.splice(index,1,user):state.users.push(user)}catch(error){return toast('Erro ao salvar usuário: '+(error.message||error))}}
  else return toast('Firebase não configurado. Não é possível gerenciar usuários.');
  save();closeModal();toast(payload.uid?'Usuário atualizado com sucesso.':'Usuário criado com sucesso.');render()
}

function setupEditObjectButton(){
  if(view!=='detail'||!selected)return;
  const actions=document.querySelector('.page-head .actions'),newEvent=[...actions?.querySelectorAll('button')||[]].find(button=>button.textContent.includes('Novo andamento'));
  if(!actions||!newEvent||actions.querySelector('[data-edit-object]'))return;
  newEvent.insertAdjacentHTML('beforebegin',`<button class="btn secondary" data-edit-object onclick="editObjectModal('${selected}')">Editar objeto</button>${session.role==='administrador'?`<button class="btn danger" data-delete-object onclick="confirmDeleteObject('${selected}')">Excluir</button>`:''}`)
}

function editObjectModal(id){
  const o=state.objects.find(item=>item.id===id);if(!o)return toast('Objeto não encontrado.');
  const areas=['Gabinete do Secretário(a)','Assessoria de Comunicação','Assessoria Jurídica','Diretoria de Ensino','Diretoria de Apoio à Educação Básica','Diretoria de Logística','Diretoria de Planejamento Gestão e Finanças'],priorities=['Baixa','Média','Alta'],statuses=['À iniciar','Em execução'];
  modal(`<div class="modal-head"><h2>Editar objeto</h2><button class="icon-btn" onclick="closeModal()">✕</button></div><div class="notice">As alterações serão registradas na auditoria e não apagarão o histórico existente.</div><form class="form-grid" onsubmit="updateObject(event,'${o.id}')"><div class="field span2"><label>Título do objeto</label><input name="title" value="${esc(o.title)}" required></div><div class="field"><label>Área</label><select name="area">${areas.map(value=>`<option ${o.area===value?'selected':''}>${value}</option>`).join('')}</select></div><div class="field"><label>Responsável principal</label><input name="owner" value="${esc(o.owner)}" required></div><div class="field"><label>Status</label><select name="status">${statuses.map(value=>`<option ${o.status===value?'selected':''}>${value}</option>`).join('')}</select></div><div class="field"><label>Prioridade</label><select name="priority">${priorities.map(value=>`<option ${o.priority===value?'selected':''}>${value}</option>`).join('')}</select></div><div class="field"><label>Início previsto</label><input type="date" name="start" value="${esc(o.start||'')}" required></div><div class="field"><label>Término previsto</label><input type="date" name="due" value="${esc(o.due||'')}" required></div><div class="field"><label>Orçamento previsto</label><input type="number" name="budget" min="0" step="0.01" value="${Number(o.budget||0)}" required></div><div class="field"><label>Produto / Entrega</label><input name="product" value="${esc(o.product||'')}" required></div><div class="field span2"><label>Descrição detalhada</label><textarea name="description" rows="4" required>${esc(o.description||'')}</textarea></div><div class="span2 actions"><button type="button" class="btn secondary" onclick="closeModal()">Cancelar</button><button class="btn">Salvar alterações</button></div></form>`)
}

async function updateObject(ev,id){
  ev.preventDefault();const o=state.objects.find(item=>item.id===id);if(!o)return;
  const f=Object.fromEntries(new FormData(ev.target)),before={title:o.title,area:o.area,owner:o.owner,status:o.status,priority:o.priority,start:o.start,due:o.due,budget:o.budget,product:o.product,description:o.description},changes={title:f.title,area:f.area,owner:f.owner,status:f.status,priority:f.priority,start:f.start,due:f.due,budget:parseBrazilianCurrency(f.budget),product:f.product,description:f.description};
  if(firebase&&o.dbId){try{const {doc,collection,writeBatch,serverTimestamp}=firebase.firestoreSdk,batch=writeBatch(firebase.db),objectRef=doc(firebase.db,'objects',o.dbId),auditRef=doc(collection(firebase.db,'audit')),eventRef=doc(collection(firebase.db,'events'));batch.update(objectRef,{title:changes.title,area:changes.area,ownerName:changes.owner,status:changes.status,priority:changes.priority,plannedStart:changes.start,plannedEnd:changes.due,budget:changes.budget,product:changes.product,description:changes.description,updatedAt:serverTimestamp(),updatedBy:session.id});batch.set(eventRef,{objectId:o.dbId,objectCode:o.id,eventType:'Edição',description:'Dados principais do objeto atualizados',createdBy:session.id,createdByName:session.name,eventAt:serverTimestamp()});batch.set(auditRef,{userId:session.id,userName:session.name,action:'UPDATE',entity:'objects',recordId:o.dbId,oldData:before,newData:changes,createdAt:serverTimestamp()});await batch.commit()}catch(error){return toast('Erro ao atualizar objeto: '+error.message)}}
  Object.assign(o,changes);state.events.unshift({id:crypto.randomUUID(),objectId:o.id,date:new Date().toLocaleString('sv-SE').slice(0,16),type:'Edição',text:'Dados principais do objeto atualizados',user:session.name});save();closeModal();toast('Objeto atualizado com sucesso.');render()
}

function confirmDeleteObject(id){
  if(session.role!=='administrador')return toast('Somente o Administrador pode excluir objetos.');
  const o=state.objects.find(item=>item.id===id);if(!o)return toast('Objeto não encontrado.');
  modal(`<div class="delete-confirm" role="alertdialog" aria-modal="true" aria-labelledby="deleteObjectTitle"><div class="delete-symbol">!</div><h2 id="deleteObjectTitle">OBJETO SERÁ EXCLUÍDO - CONFIRMA EXCLUSÃO?</h2><p>${esc(o.id)} · ${esc(o.title)}</p><div class="delete-actions"><button type="button" class="btn secondary" onclick="closeModal()">Não</button><button type="button" class="btn danger" onclick="deleteObject('${o.id}')">Sim</button></div></div>`)
}

async function deleteObject(id){
  if(session.role!=='administrador')return toast('Somente o Administrador pode excluir objetos.');
  const index=state.objects.findIndex(item=>item.id===id),o=state.objects[index];if(index<0||!o)return toast('Objeto não encontrado.');
  if(firebase&&o.dbId){try{const {doc,collection,writeBatch,serverTimestamp}=firebase.firestoreSdk,batch=writeBatch(firebase.db),objectRef=doc(firebase.db,'objects',o.dbId),eventRef=doc(collection(firebase.db,'events')),auditRef=doc(collection(firebase.db,'audit'));batch.update(objectRef,{active:false,deletedAt:serverTimestamp(),deletedBy:session.id,updatedAt:serverTimestamp()});batch.set(eventRef,{objectId:o.dbId,objectCode:o.id,eventType:'Exclusão',description:'Objeto excluído pelo administrador',createdBy:session.id,createdByName:session.name,eventAt:serverTimestamp()});batch.set(auditRef,{userId:session.id,userName:session.name,action:'DELETE',entity:'objects',recordId:o.dbId,oldData:{code:o.id,title:o.title,active:true},newData:{active:false},createdAt:serverTimestamp()});await batch.commit()}catch(error){return toast('Erro ao excluir objeto: '+error.message)}}
  state.objects.splice(index,1);state.events.unshift({id:crypto.randomUUID(),objectId:o.id,date:new Date().toLocaleString('sv-SE').slice(0,16),type:'Exclusão',text:'Objeto excluído pelo administrador',user:session.name});save();closeModal();selected=null;view='objects';toast('Objeto excluído com sucesso.');render()
}

objectModal=function(){
  const primaryAreas=['Gabinete do Secretário(a)','Assessoria de Comunicação','Assessoria Jurídica','Diretoria de Ensino','Diretoria de Apoio à Educação Básica','Diretoria de Logística','Diretoria de Planejamento Gestão e Finanças'],secondaryAreas=['Educação Infantil','Educação Fundamental','DETIC','Inspeção','Núcleo de Avaliação','Transporte','Patrimônio','Infraestrutura','Recursos Humanos','Monitoramento de Contratos','Programas Federais','Planejamento','Arte e Cultura','Céu das Artes','CREI','CEMEA Boa Vista'];
  modal(`<div class="modal-head"><h2>Novo objeto</h2><button class="icon-btn" onclick="closeModal()">✕</button></div><div class="notice">Preencha os dados na sequência abaixo. A duração será calculada automaticamente.</div><form class="form-grid object-create-form" onsubmit="addObject(event)"><div class="field span2"><label>1. Título do Objeto</label><input name="title" required></div><div class="field span2"><label>2. Produto / Entrega</label><input name="product" required></div><div class="field"><label>3. Tipo</label><select name="objectType" required><option>Projeto</option><option>Processo</option><option>Programa</option><option>Contrato</option><option>Aquisição</option></select></div><div class="field"><label>4. Prioridade</label><select name="priority" required><option>Baixa</option><option selected>Média</option><option>Alta</option></select></div><div class="field span2"><label>5. Orçamento previsto (em R$)</label><div class="currency-input"><span>R$</span><input type="number" name="budget" min="0" step="0.01" value="0" required></div></div><div class="field"><label>6. Previsão de Início</label><input type="date" name="start" onchange="calculateObjectDuration(this.form)" required></div><div class="field"><label>7. Previsão de Término</label><input type="date" name="due" onchange="calculateObjectDuration(this.form)" required></div><div class="field span2"><label>8. Duração (em dias)</label><output class="object-duration" id="objectDuration" aria-live="polite"><strong>—</strong><span>Informe as datas de início e término</span></output><input type="hidden" name="duration"></div><div class="field"><label>9. Status</label><select name="status" required><option>À iniciar</option><option>Em execução</option></select></div><div class="field"><label>10. Tipo de intervenção</label><select name="interventionType" required><option>Construção</option><option>Reforma</option><option>Licitação</option><option>Modernização</option></select></div><div class="field span2"><label>11. Responsável Principal</label><input name="owner" required></div><div class="field span2"><label>12. Área Principal</label><select name="primaryArea" required>${primaryAreas.map(area=>`<option>${area}</option>`).join('')}</select></div><div class="field span2"><label>13. Área Secundária</label><select name="secondaryArea" required>${secondaryAreas.map(area=>`<option>${area}</option>`).join('')}</select></div><div class="field span2"><label>14. Observação</label><textarea name="observation" rows="4"></textarea></div><div class="span2 actions"><button type="button" class="btn secondary" onclick="closeModal()">Cancelar</button><button class="btn">Cadastrar objeto</button></div></form>`)
};

const renderUnfilteredObjectModal=objectModal;
objectModal=function(){
  renderUnfilteredObjectModal();
  const form=document.querySelector('#modal .object-create-form'),primary=form?.elements.primaryArea;if(!primary)return;
  primary.addEventListener('change',()=>updateObjectSecondaryAreas(primary));
  updateObjectSecondaryAreas(primary)
};

function updateObjectSecondaryAreas(primarySelect){
  const all=['Educação Infantil','Educação Fundamental','DETIC','Inspeção','Núcleo de Avaliação','Arte e Cultura','CREI','CEMEA Boa Vista','CEU das Artes','Biblioteca','Infraestrutura','Recursos Humanos','Patrimônio','Transporte','Nutrição','Programas Federais','Monitoramento de Contratos','Planejamento'],byArea={
    'Diretoria de Ensino':['Educação Infantil','Educação Fundamental','DETIC','Inspeção','Núcleo de Avaliação'],
    'Diretoria de Apoio à Educação Básica':['Arte e Cultura','CREI','CEMEA Boa Vista','CEU das Artes','Biblioteca'],
    'Diretoria de Logística':['Infraestrutura','Recursos Humanos','Patrimônio','Transporte','Nutrição'],
    'Diretoria de Planejamento Gestão e Finanças':['Programas Federais','Monitoramento de Contratos','Planejamento']
  },secondary=primarySelect.form?.elements.secondaryArea,options=byArea[primarySelect.value]||all,current=secondary?.value;
  if(!secondary)return;secondary.innerHTML=options.map(area=>`<option value="${esc(area)}" ${current===area?'selected':''}>${esc(area)}</option>`).join('')
}

function calculateObjectDuration(form){
  const start=form?.elements.start,due=form?.elements.due,duration=form?.elements.duration,output=document.getElementById('objectDuration');if(!start||!due||!duration||!output)return null;
  if(!start.value||!due.value){duration.value='';due.setCustomValidity('');output.classList.remove('invalid');output.innerHTML='<strong>—</strong><span>Informe as datas de início e término</span>';return null}
  const days=Math.round((new Date(`${due.value}T12:00:00`)-new Date(`${start.value}T12:00:00`))/86400000);
  if(days<0){duration.value='';due.setCustomValidity('A previsão de término deve ser igual ou posterior à previsão de início.');output.classList.add('invalid');output.innerHTML='<strong>Data inválida</strong><span>O término deve ser posterior ao início</span>';return null}
  due.setCustomValidity('');duration.value=String(days);output.classList.remove('invalid');output.innerHTML=`<strong>${days} ${days===1?'dia':'dias'}</strong><span>Duração prevista</span>`;return days
}

addObject=async function(ev){
  ev.preventDefault();const form=ev.target,duration=calculateObjectDuration(form);if(duration===null){form.reportValidity();return}const f=Object.fromEntries(new FormData(form)),n=String(Math.max(0,...state.objects.map(o=>+o.id.split('-').pop()))+1).padStart(3,'0'),code=`OBJ-${new Date().getFullYear()}-${n}`,o={id:code,title:f.title,product:f.product,objectType:f.objectType,priority:f.priority,budget:parseBrazilianCurrency(f.budget),start:f.start,due:f.due,duration:+f.duration,status:f.status,interventionType:f.interventionType,owner:f.owner,area:f.primaryArea,primaryArea:f.primaryArea,secondaryArea:f.secondaryArea,observation:f.observation||'',description:f.observation||'',progress:0,spent:0};
  if(firebase){try{const {collection,doc,writeBatch,serverTimestamp}=firebase.firestoreSdk,objectRef=doc(collection(firebase.db,'objects')),eventRef=doc(collection(firebase.db,'events')),auditRef=doc(collection(firebase.db,'audit')),batch=writeBatch(firebase.db),objectData={code,title:o.title,product:o.product,objectType:o.objectType,priority:o.priority,budget:o.budget,plannedStart:o.start,plannedEnd:o.due,duration:o.duration,status:o.status,interventionType:o.interventionType,ownerName:o.owner,area:o.area,primaryArea:o.primaryArea,secondaryArea:o.secondaryArea,observation:o.observation,description:o.description,progress:0,spent:0,active:true,createdBy:session.id,createdAt:serverTimestamp(),updatedAt:serverTimestamp()};batch.set(objectRef,objectData);batch.set(eventRef,{objectId:objectRef.id,objectCode:code,eventType:'Criação',description:'Objeto cadastrado no sistema',createdBy:session.id,createdByName:session.name,eventAt:serverTimestamp()});batch.set(auditRef,{userId:session.id,userName:session.name,action:'CREATE',entity:'objects',recordId:objectRef.id,newData:objectData,createdAt:serverTimestamp()});await batch.commit();o.dbId=objectRef.id}catch(error){return toast('Erro ao cadastrar objeto: '+error.message)}}
  state.objects.unshift(o);state.events.unshift({id:crypto.randomUUID(),objectId:o.id,date:new Date().toLocaleString('sv-SE').slice(0,16),type:'Criação',text:'Objeto cadastrado no sistema',user:session.name});save();closeModal();toast('Objeto cadastrado com sucesso.');openObject(o.id)
};

const openBaseModal=modal;
modal=function(html){
  openBaseModal(html);const root=document.getElementById('modal');if(!root)return;
  setupUppercaseDescriptions(root);root.querySelectorAll('input[name="budget"],input[data-currency]').forEach(setupBrazilianCurrencyInput)
};

function setupUppercaseDescriptions(root){
  const fields=root.querySelectorAll('input:not([type]),input[type="text"],textarea');
  fields.forEach(field=>{if(['uid'].includes(field.name)||field.classList.contains('search'))return;const upper=()=>{const start=field.selectionStart,end=field.selectionEnd;field.value=field.value.toLocaleUpperCase('pt-BR');if(start!==null)field.setSelectionRange(start,end)};upper();field.addEventListener('input',upper)})
}

function setupBrazilianCurrencyInput(input){
  if(input.dataset.currencyReady)return;input.dataset.currencyReady='true';const numeric=Number(input.value||0);input.type='text';input.inputMode='numeric';input.removeAttribute('min');input.removeAttribute('step');
  if(!input.closest('.currency-input')){const wrapper=document.createElement('div');wrapper.className='currency-input';input.parentNode.insertBefore(wrapper,input);wrapper.insertAdjacentHTML('afterbegin','<span>R$</span>');wrapper.appendChild(input)}
  const format=()=>{const digits=input.value.replace(/\D/g,'');const value=Number(digits||0)/100;input.value=value.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})};input.value=numeric.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});input.addEventListener('input',format);input.addEventListener('focus',()=>input.select())
}

function parseBrazilianCurrency(value){
  const normalized=String(value??'0').replace(/[^\d,.-]/g,'').replace(/\./g,'').replace(',','.');const parsed=Number(normalized);return Number.isFinite(parsed)?parsed:0
}

importView=function(){
  return head('Integrações','Importar planilha','Importe objetos com os campos e valores reconhecidos pelo sistema.')+`<section class="panel import-panel"><div class="notice"><strong>Importação segura:</strong> divergências são apresentadas antes da confirmação e nenhum histórico existente é apagado.</div><article class="import-template-card"><div class="import-template-icon" aria-hidden="true">XLSX</div><div><span class="eyebrow">MODELO OFICIAL SEMED</span><h2>Baixe a planilha modelo antes de importar</h2><p>O arquivo contém todos os campos obrigatórios e opcionais, exemplo preenchido, cálculo automático da duração, listas de valores aceitos e as regras de relacionamento entre Área Principal e Área Secundária.</p><div class="template-features"><span>14 campos documentados</span><span>Valores com validação</span><span>Datas e moeda padronizadas</span></div></div><a class="btn template-download" href="assets/modelo-importacao-objetos-semed.xlsx" download="modelo-importacao-objetos-semed.xlsx" onclick="toast('Download da planilha modelo iniciado.')">↓ Baixar planilha modelo</a></article><div class="upload" onclick="fileInput.click()" role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();fileInput.click()}"><h2>Arraste sua planilha ou clique para selecionar</h2><p>Excel (.xlsx, .xls) ou CSV · validação e conciliação de duplicidades</p><button type="button" class="btn">Selecionar arquivo</button></div><div class="summary" style="margin-top:18px"><div><span>1. Envio</span><strong>Arquivo de origem</strong></div><div><span>2. Validação</span><strong>Mapeamento de colunas</strong></div><div><span>3. Conciliação</span><strong>Prévia e confirmação</strong></div></div></section>`
};

objectsView=function(){
  const statusFilters=['À iniciar','Em execução','Concluído','Atrasado','Alta prioridade'];
  const matchesStatus=o=>filter==='all'||(filter==='Concluído'?o.progress>=100:filter==='Atrasado'?Boolean(o.due)&&new Date(`${o.due}T23:59:59`)<new Date()&&o.progress<100:filter==='Alta prioridade'?o.priority==='Alta'&&o.progress<100:o.status===filter),matchesSearch=o=>JSON.stringify(o).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')),list=state.objects.filter(o=>matchesStatus(o)&&matchesSearch(o));
  return head('Carteira','Objetos SEMED','Cadastre, filtre e acompanhe todos os objetos institucionais.',`<button class="btn secondary" onclick="exportCSV()">↓ Exportar CSV</button><button class="btn" onclick="objectModal()">+ Novo objeto</button>`)+`<div class="panel"><div class="toolbar"><input class="search" aria-label="Buscar objetos" placeholder="Buscar na carteira..." value="${esc(query)}" oninput="query=this.value;render()"><select aria-label="Filtrar por status" onchange="filter=this.value;render()"><option value="all">Todos os status</option>${statusFilters.map(status=>`<option value="${status}" ${filter===status?'selected':''}>${status}</option>`).join('')}</select><button class="btn secondary" onclick="query='';filter='all';render()">Limpar filtros</button></div>${objectTable(list)}</div>`
};

const reportDefinitions=[
  ['executive','Relatório Executivo','Indicadores, riscos, atrasos e decisões necessárias.'],
  ['general','Relatório Geral','Consolidação completa dos objetos e seus vínculos.'],
  ['financial','Execução Financeira','Previsto, realizado, comprometido e saldo.'],
  ['late','Objetos em Atraso','Prazos vencidos e justificativas registradas.'],
  ['pending','Pendências','Pendências abertas, vencidas e responsáveis.'],
  ['audit','Auditoria','Rastreabilidade de alterações e usuários.']
];

reports=function(){return head('Análises','Central de Relatórios','Gere, confira e imprima os relatórios institucionais em padrão A4.')+`<div class="report-grid functional-reports">${reportDefinitions.map(r=>`<article class="report"><span class="eyebrow">Relatório</span><h3>${r[1]}</h3><p>${r[2]}</p><div class="report-actions"><button class="btn secondary" onclick="openReport('${r[0]}')">Visualizar</button><button class="btn" onclick="printReport('${r[0]}')">Imprimir</button></div></article>`).join('')}</div>`};

function filteredReportObjects(){return state.objects.filter(o=>(filter==='all'||o.status===filter)&&(!query||JSON.stringify(o).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR'))))}
function reportTable(headers,rows){return `<table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(value=>`<td>${value??'—'}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${headers.length}" class="report-empty">NENHUM REGISTRO ENCONTRADO.</td></tr>`}</tbody></table>`}
function reportHeader(title){return `<header class="print-report-header"><div><strong>SECRETARIA MUNICIPAL DE EDUCAÇÃO DE UBERABA</strong><h1>${esc(title)}</h1></div><div><span>Emitido em ${new Date().toLocaleString('pt-BR')}</span><span>Usuário: ${esc(session.name)}</span></div></header>`}

function buildReport(type){
  const objects=filteredReportObjects(),now=new Date(),late=objects.filter(o=>o.due&&new Date(`${o.due}T23:59:59`)<now&&!/Concluído|Finalizado/i.test(o.status)),budget=objects.reduce((sum,o)=>sum+Number(o.budget||0),0),spent=objects.reduce((sum,o)=>sum+Number(o.spent||0),0),committed=state.costs.filter(c=>objects.some(o=>o.id===c.objectId)).reduce((sum,c)=>sum+Number(c.value||0),0),definition=reportDefinitions.find(r=>r[0]===type)||reportDefinitions[0];let body='';
  if(type==='executive'){const critical=objects.filter(o=>o.priority==='Alta'||/Bloqueado|Parado/i.test(o.status));body=`<section class="print-kpis"><div><span>OBJETOS</span><strong>${objects.length}</strong></div><div><span>PROGRESSO MÉDIO</span><strong>${objects.length?Math.round(objects.reduce((s,o)=>s+Number(o.progress||0),0)/objects.length):0}%</strong></div><div><span>EM ATRASO</span><strong>${late.length}</strong></div><div><span>ORÇAMENTO</span><strong>${money(budget)}</strong></div><div><span>REALIZADO</span><strong>${money(spent)}</strong></div></section><h2>OBJETOS QUE EXIGEM ATENÇÃO</h2>${reportTable(['Código','Objeto','Área','Responsável','Prioridade','Status','Progresso','Prazo'],critical.map(o=>[esc(o.id),esc(o.title),esc(o.area),esc(o.owner),esc(o.priority),esc(o.status),`${Number(o.progress||0)}%`,date(o.due)]))}`}
  else if(type==='general')body=reportTable(['Código','Objeto','Produto/Entrega','Tipo','Área Principal','Área Secundária','Responsável','Status','Prioridade','Início','Término','Duração','Progresso'],objects.map(o=>[esc(o.id),esc(o.title),esc(o.product),esc(o.objectType||''),esc(o.primaryArea||o.area),esc(o.secondaryArea||''),esc(o.owner),esc(o.status),esc(o.priority),date(o.start),date(o.due),`${Number(o.duration||0)} dias`,`${Number(o.progress||0)}%`]));
  else if(type==='financial')body=`<section class="print-kpis"><div><span>PREVISTO</span><strong>${money(budget)}</strong></div><div><span>REALIZADO</span><strong>${money(spent)}</strong></div><div><span>COMPROMETIDO</span><strong>${money(committed)}</strong></div><div><span>SALDO</span><strong>${money(budget-spent)}</strong></div></section>${reportTable(['Código','Objeto','Orçamento previsto','Realizado','Comprometido','Saldo','Execução'],objects.map(o=>{const commitment=state.costs.filter(c=>c.objectId===o.id).reduce((s,c)=>s+Number(c.value||0),0);return[esc(o.id),esc(o.title),money(o.budget),money(o.spent),money(commitment),money(Number(o.budget||0)-Number(o.spent||0)),`${o.budget?Math.round(Number(o.spent||0)/Number(o.budget)*100):0}%`]}))}`;
  else if(type==='late')body=reportTable(['Código','Objeto','Responsável','Área','Status','Prazo final','Dias em atraso','Última justificativa'],late.map(o=>{const days=Math.max(0,Math.floor((now-new Date(`${o.due}T12:00:00`))/86400000)),last=[...state.events].find(e=>e.objectId===o.id);return[esc(o.id),esc(o.title),esc(o.owner),esc(o.area),esc(o.status),date(o.due),days,esc(last?.text||'SEM JUSTIFICATIVA REGISTRADA')]}));
  else if(type==='pending'){const pending=state.events.filter(e=>objects.some(o=>o.id===e.objectId)&&e.status!=='finalizado'&&(e.type==='Pendência'||['a_iniciar','a_executar','em_andamento','em_execucao','parado'].includes(e.status))),rows=pending.map(e=>{const deadline=e.forecastEnd||e.executionEnd||'',overdue=deadline&&new Date(`${deadline}T23:59:59`)<now;return[esc(e.objectId),esc(e.text||e.productDelivery||e.type),esc(e.assignedToName||e.responsible||'NÃO DEFINIDO'),esc(eventStatusLabel(e.status)),deadline?date(deadline):'—',overdue?'VENCIDA':'ABERTA',esc(e.user)]});body=reportTable(['Objeto','Pendência/Andamento','Responsável','Status','Prazo','Situação','Registrado por'],rows)}
  else body=reportTable(['Data','Usuário','Ação','Objeto','Descrição','Status'],[...state.events].sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(e=>[esc(e.date),esc(e.user),esc(e.type),esc(e.objectId),esc(e.text),esc(eventStatusLabel(e.status))]));
  return{title:definition[1],html:`${reportHeader(definition[1])}<p class="print-report-description">${esc(definition[2])}</p>${body}<footer class="print-report-footer">MONITORAMENTO E CONTROLE SEMED · ${objects.length} objeto${objects.length===1?'':'s'} considerado${objects.length===1?'':'s'}</footer>`}
}

function openReport(type,printAfter=false){const report=buildReport(type);modal(`<div class="modal-head report-screen-actions"><div><span class="eyebrow">Pré-visualização</span><h2>${esc(report.title)}</h2></div><div class="actions"><button class="btn secondary" onclick="closeModal()">Fechar</button><button class="btn" onclick="window.print()">Imprimir</button></div></div><div class="report-print-shell"><section class="print-report" id="printReport">${report.html}</section></div>`);if(printAfter)setTimeout(()=>window.print(),120)}
function printReport(type){openReport(type,true)}

let selectedTimelineObject=null;
const navigateBase=go;
go=function(target){if(target==='timeline')selectedTimelineObject=null;navigateBase(target)};

timelineView=function(){
  if(!selectedTimelineObject)return head('Histórico permanente','Timeline por objeto','Selecione um objeto para consultar seu histórico completo.')+`<section class="timeline-object-grid" aria-label="Objetos disponíveis">${state.objects.map(o=>`<button class="timeline-object-card" onclick="openObjectTimeline('${o.id}')"><span class="timeline-object-code">${esc(o.id)}</span><strong>${esc(o.title)}</strong><small>${esc(o.product||o.description||'SEM SÍNTESE CADASTRADA')}</small></button>`).join('')||'<div class="empty">NENHUM OBJETO CADASTRADO.</div>'}</section>`;
  const o=state.objects.find(item=>item.id===selectedTimelineObject);if(!o){selectedTimelineObject=null;return timelineView()}const events=state.events.filter(e=>e.objectId===o.id).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  return head('Timeline do objeto',o.id,esc(o.title),`<button class="btn secondary" onclick="backToTimelineObjects()">← Voltar aos objetos</button><button class="btn" onclick="eventModal('${o.id}')">+ Novo andamento</button>`)+`<section class="panel object-timeline-panel"><div class="panel-head"><div><h2>${esc(o.id)}</h2><small>${events.length} registro${events.length===1?'':'s'} no histórico</small></div><span class="pill ${statusClass(o.status)}">${esc(o.status)}</span></div><div class="timeline">${events.map(e=>`<article class="event"><div class="event-title-row"><strong>${esc(e.type)}</strong>${e.status?`<span class="pill ${e.status==='finalizado'?'green':'blue'}">${esc(eventStatusLabel(e.status))}</span>`:''}</div><p>${esc(e.text||e.productDelivery||'SEM DESCRIÇÃO')}</p>${e.productDelivery?`<div class="timeline-detail"><span>PRODUTO / ENTREGA</span><strong>${esc(e.productDelivery)}</strong></div>`:''}${e.assignedToName?`<div class="timeline-detail"><span>DIRECIONADO PARA</span><strong>${esc(e.assignedToName)}</strong></div>`:''}${e.status?eventProgressBar(e):''}${eventDatesHtml(e)}<small>${esc(e.date)} · ${esc(e.user)}</small></article>`).join('')||'<div class="empty">ESTE OBJETO AINDA NÃO POSSUI REGISTROS NA TIMELINE.</div>'}</div></section>`
};

function openObjectTimeline(id){selectedTimelineObject=id;render();window.scrollTo({top:0,behavior:'smooth'})}
function backToTimelineObjects(){selectedTimelineObject=null;render();window.scrollTo({top:0,behavior:'smooth'})}

financial=function(){
  const activeObjects=state.objects,activeIds=new Set(activeObjects.map(o=>o.id)),recentCosts=state.costs.filter(c=>activeIds.has(c.objectId)).sort((a,b)=>(b.date||'').localeCompare(a.date||'')),total=activeObjects.reduce((sum,o)=>sum+Number(o.budget||0),0),spent=activeObjects.reduce((sum,o)=>sum+Number(o.spent||0),0),committed=recentCosts.reduce((sum,c)=>sum+Number(c.value||0),0);
  return head('Controle financeiro','Execução Financeira','Somente objetos ativos e seus respectivos lançamentos financeiros.',`<button class="btn secondary" onclick="exportCSV()">Exportar</button>`)+`<section class="kpis financial-kpis"><article class="kpi"><span class="label">Orçamento previsto</span><strong>${money(total)}</strong></article><article class="kpi"><span class="label">Realizado</span><strong>${money(spent)}</strong></article><article class="kpi"><span class="label">Comprometido</span><strong>${money(committed)}</strong></article><article class="kpi"><span class="label">Saldo disponível</span><strong>${money(total-spent)}</strong></article></section><section class="panel" style="margin-top:15px"><div class="panel-head"><h2>Lançamentos recentes</h2><span class="pill blue">${recentCosts.length} lançamento${recentCosts.length===1?'':'s'}</span></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Objeto ativo</th><th>Categoria</th><th>Fornecedor</th><th>Valor</th><th></th></tr></thead><tbody>${recentCosts.map(c=>{const o=activeObjects.find(item=>item.id===c.objectId);return`<tr><td>${date(c.date)}</td><td><button class="link" onclick="openObjectFinancial('${c.objectId}')">${esc(c.objectId)}</button><br><strong>${esc(o?.title||'')}</strong></td><td>${esc(c.category)}</td><td>${esc(c.supplier)}</td><td><strong>${money(c.value)}</strong></td><td><button class="btn secondary financial-view-btn" onclick="openObjectFinancial('${c.objectId}')">Demonstrativo</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">NENHUM LANÇAMENTO DE OBJETO ATIVO.</td></tr>'}</tbody></table></div></section>`
};

function openObjectFinancial(objectId){
  const o=state.objects.find(item=>item.id===objectId);if(!o)return toast('O objeto não está ativo.');const costs=state.costs.filter(c=>c.objectId===objectId).sort((a,b)=>(b.date||'').localeCompare(a.date||'')),committed=costs.reduce((sum,c)=>sum+Number(c.value||0),0),budget=Number(o.budget||0),spent=Number(o.spent||0),percentage=budget?Math.min(100,Math.round(spent/budget*100)):0;
  modal(`<div class="modal-head"><div><span class="eyebrow">Demonstrativo financeiro</span><h2>${esc(o.id)}</h2></div><button class="icon-btn" onclick="closeModal()">✕</button></div><section class="financial-statement"><header><div><span>OBJETO ATIVO</span><strong>${esc(o.title)}</strong></div><span class="pill ${statusClass(o.status)}">${esc(o.status)}</span></header><div class="financial-statement-kpis"><div><span>ORÇAMENTO PREVISTO</span><strong>${money(budget)}</strong></div><div><span>REALIZADO</span><strong>${money(spent)}</strong></div><div><span>COMPROMETIDO</span><strong>${money(committed)}</strong></div><div><span>SALDO DISPONÍVEL</span><strong>${money(budget-spent)}</strong></div></div><div class="financial-execution"><div><span>EXECUÇÃO FINANCEIRA</span><strong>${percentage}%</strong></div><div class="progress"><i style="--p:${percentage}%"></i></div></div><div class="panel-head"><h2>Lançamentos do objeto</h2><span class="pill blue">${costs.length}</span></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Categoria</th><th>Fornecedor</th><th>Valor</th></tr></thead><tbody>${costs.map(c=>`<tr><td>${date(c.date)}</td><td>${esc(c.category)}</td><td>${esc(c.supplier)}</td><td><strong>${money(c.value)}</strong></td></tr>`).join('')||'<tr><td colspan="4" class="empty">SEM LANÇAMENTOS FINANCEIROS.</td></tr>'}</tbody></table></div></section><div class="actions financial-statement-actions"><button class="btn secondary" onclick="closeModal()">Fechar</button></div>`)
}
